# Step 4: public review display. New StarRatingDisplay and ReviewCard
# components, a full Reviews section wired into the product detail page,
# and fixes the rating/reviewCount fields that have been hardcoded to
# undefined this entire build in both the detail page and the shared
# products.ts used by the homepage, /products grid, and Related section.

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\StarRatingDisplay.tsx"), $bytes)
Write-Host "NEW: src\components\StarRatingDisplay.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\components\ReviewCard.tsx"), $bytes)
Write-Host "NEW: src\components\ReviewCard.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\products\[slug]\page.tsx"), $bytes)
Write-Host "UPDATED: src\app\products\[slug]\page.tsx" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\lib\products.ts"), $bytes)
Write-Host "UPDATED: src\lib\products.ts" -ForegroundColor Green

Write-Host "`nAll 4 files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan